// AULA Setup Request
// Initializes poll state (on fresh Inject) or reads existing state (on loop-back).
// Builds the HA REST API request for the current polling phase.
//
// State machine phases:
//   'threads' — fetching paginated thread list via messaging.getThreads
//   'messages' — fetching messages per thread via messaging.getMessagesForThread
//
// Required env vars: HA_URL, HA_TOKEN

let HA_URL = (env.get('HA_URL') || 'http://homeassistant.local:8123').trim();
if (HA_URL[HA_URL.length - 1] === '/') HA_URL = HA_URL.slice(0, -1);

const HA_TOKEN = env.get('HA_TOKEN');
if (!HA_TOKEN) {
    node.error('Missing HA_TOKEN. Create a Long-Lived Token in HA: Profile → Security → Long-Lived Access Tokens.', msg);
    node.status({ fill: 'red', shape: 'ring', text: 'No HA_TOKEN' });
    return null;
}

// Fresh poll when triggered by Inject (msg.topic === 'poll') or state is absent
let state = flow.get('aula_state');
if (!state || msg.topic === 'poll') {
    state = {
        phase: 'threads',
        threads: [],
        threadPage: 0,
        threadIdx: 0,
        msgPage: 0,
        currentMsgs: [],
        enriched: []
    };
    // Change topic so loop-back messages are not mistaken for a fresh poll
    msg.topic = 'aula-loop';
    node.status({ fill: 'blue', shape: 'ring', text: 'Starter poll...' });
}

// Determine which AULA API method to call based on current phase
let uri;
if (state.phase === 'threads') {
    uri = '?method=messaging.getThreads&sortOn=date&orderDirection=desc&page=' + state.threadPage;
    node.status({ fill: 'blue', shape: 'dot', text: 'Tråde s.' + state.threadPage });
} else {
    const t = state.threads[state.threadIdx];
    uri = '?method=messaging.getMessagesForThread&threadId=' + t.id + '&page=' + state.msgPage;
    node.status({ fill: 'blue', shape: 'dot', text: 'Beskeder ' + (state.threadIdx + 1) + '/' + state.threads.length });
}

flow.set('aula_state', state);

// Set HTTP request properties read by the http request node downstream
msg.url = HA_URL + '/api/services/aula/api_call?return_response';
msg.method = 'POST';
msg.headers = {
    'Authorization': 'Bearer ' + HA_TOKEN,
    'Content-Type': 'application/json'
};
msg.payload = { uri: uri };

return msg;

// AULA Process Response
// Processes the HA API response and advances the state machine.
//
// Output 1 — loop back to Setup Request (more pages to fetch)
// Output 2 — done, send to MQTT Formatter

let state = flow.get('aula_state');
if (!state) {
    node.error('Poll-tilstand mangler — genstart poll via Inject', msg);
    return null;
}

// Check HTTP status
if (msg.statusCode < 200 || msg.statusCode >= 300) {
    node.error('HA HTTP ' + msg.statusCode + ': ' + JSON.stringify(msg.payload).slice(0, 200), msg);
    flow.set('aula_state', null);
    node.status({ fill: 'red', shape: 'ring', text: 'HTTP ' + msg.statusCode });
    return null;
}

// Unwrap HA service_response envelope: { service_response: <aula_json> }
const body = msg.payload;
const aula = (body && body.service_response !== undefined) ? body.service_response : body;

if (state.phase === 'threads') {
    // ── Thread pagination ──────────────────────────────────────────────────────
    if (!aula || !aula.data || !aula.data.threads) {
        node.error('Uventet getThreads-svar: ' + JSON.stringify(aula).slice(0, 200), msg);
        flow.set('aula_state', null);
        return null;
    }
    const pageThreads = aula.data.threads;
    state.threads = state.threads.concat(pageThreads);

    if (pageThreads.length >= 10) {
        // AULA returns up to 10 per page; exactly 10 means there may be more
        state.threadPage++;
        flow.set('aula_state', state);
        return [msg, null]; // output 1: loop — fetch next thread page
    }

    // All thread pages fetched — switch to message phase
    state.phase = 'messages';
    state.threadIdx = 0;
    state.msgPage = 0;
    state.currentMsgs = [];
    flow.set('aula_state', state);

    if (state.threads.length === 0) {
        // No threads at all — publish empty result immediately
        flow.set('aula_state', null);
        msg.payload = { timestamp: new Date().toISOString(), threadCount: 0, unreadCount: 0, threads: [] };
        node.status({ fill: 'green', shape: 'dot', text: '0 tråde' });
        return [null, msg]; // output 2: done
    }
    return [msg, null]; // output 1: loop — start fetching first thread's messages

} else {
    // ── Message pagination ─────────────────────────────────────────────────────
    const pageMsgs = (aula && aula.data && aula.data.messages) ? aula.data.messages : [];
    state.currentMsgs = state.currentMsgs.concat(pageMsgs);

    if (pageMsgs.length >= 20) {
        // More message pages for current thread
        state.msgPage++;
        flow.set('aula_state', state);
        return [msg, null]; // output 1: loop
    }

    // Done with this thread's messages — store and move to next thread
    state.enriched.push({
        thread: state.threads[state.threadIdx],
        messages: state.currentMsgs
    });
    state.threadIdx++;

    if (state.threadIdx < state.threads.length) {
        state.msgPage = 0;
        state.currentMsgs = [];
        flow.set('aula_state', state);
        return [msg, null]; // output 1: loop — fetch next thread's messages
    }

    // ── All threads and messages fetched ───────────────────────────────────────
    const unreadCount = state.threads.filter(function (t) { return !t.read; }).length;
    msg.payload = {
        timestamp: new Date().toISOString(),
        threadCount: state.threads.length,
        unreadCount: unreadCount,
        threads: state.enriched
    };
    flow.set('aula_state', null);
    node.status({ fill: 'green', shape: 'dot', text: state.threads.length + ' tråde, ' + unreadCount + ' ulæste' });
    return [null, msg]; // output 2: done — forward to MQTT Formatter
}

// AULA MQTT Formatter
// Converts raw AULA thread data into per-topic MQTT messages.
// Returns an array so Node-RED sends each element as a separate message.
//
// Topics (relative to PREFIX):
//   {PREFIX}          — full thread summary (retained)
//   {PREFIX}/status   — heartbeat with counts (retained)
//   {PREFIX}/{id}     — per-thread detail with messages (retained)
//   {PREFIX}/unread   — unread threads only (NOT retained)

const PREFIX = env.get('MQTT_TOPIC_PREFIX') || 'aula/messages';
const data = msg.payload;

if (!data || !data.threads) { node.warn('Ingen AULA-data at publicere'); return null; }

function stripHtml(html) {
    if (!html) return '';
    return String(html).replace(/<[^>]+>/g, ' ').replace(/\s+/g, ' ').trim();
}

const out = [];

// 1. Status/heartbeat
out.push({
    topic: PREFIX + '/status',
    payload: JSON.stringify({ timestamp: data.timestamp, threadCount: data.threadCount, unreadCount: data.unreadCount }),
    qos: 1,
    retain: true
});

// 2. Summary of all threads
out.push({
    topic: PREFIX,
    payload: JSON.stringify({
        timestamp: data.timestamp,
        threadCount: data.threadCount,
        unreadCount: data.unreadCount,
        threads: data.threads.map(function (item) {
            return { id: item.thread.id, subject: item.thread.subject || '', read: item.thread.read || false, messageCount: item.messages.length };
        })
    }),
    qos: 1,
    retain: true
});

// 3. Per-thread detail
data.threads.forEach(function (item) {
    var t = item.thread;
    var formatted = item.messages
        .filter(function (m) { return !m.messageType || m.messageType === 'Message'; })
        .map(function (m) {
            var text = '';
            try { text = (m.text && m.text.html) ? stripHtml(m.text.html) : stripHtml(String(m.text || '')); } catch (e) {}
            return {
                id: m.id,
                sendDateTime: m.sendDateTime,
                sender: (m.sender && m.sender.fullName) ? m.sender.fullName : 'Unknown',
                text: text,
                messageType: m.messageType || 'Message'
            };
        });
    out.push({
        topic: PREFIX + '/' + t.id,
        payload: JSON.stringify({ id: t.id, subject: t.subject || '', read: t.read || false, messageCount: formatted.length, messages: formatted }),
        qos: 1,
        retain: true
    });
});

// 4. Unread only (not retained — for HA automations)
var unread = data.threads.filter(function (item) { return !item.thread.read; });
if (unread.length > 0) {
    out.push({
        topic: PREFIX + '/unread',
        payload: JSON.stringify({ timestamp: data.timestamp, count: unread.length, threads: unread.map(function (item) { return { id: item.thread.id, subject: item.thread.subject || '' }; }) }),
        qos: 0,
        retain: false
    });
}

return [out];
